// sensors/<zone>/<measurement> → msg.zone, msg.measurement and a numeric
// msg.payload. Accepts {"value": 23.4, ...} or a bare number, like Telegraf.
const parts = msg.topic.split("/");
if (parts.length !== 3 || !parts[1] || !parts[2]) {
    return null;
}
let value = msg.payload;
if (value !== null && typeof value === "object") {
    value = value.value;
}
if (typeof value === "string") {
    value = value.trim() === "" ? NaN : Number(value);
}
if (typeof value !== "number" || !Number.isFinite(value)) {
    return null;
}
msg.zone = parts[1];
msg.measurement = parts[2];
msg.payload = value;

// When each zone last reported each measurement, for the valve watchdog
const seen = flow.get("seen") || {};
seen[msg.zone] = Object.assign(seen[msg.zone] || {}, { [msg.measurement]: Date.now() });
flow.set("seen", seen);
return msg;

// Number from the container environment (.env), or the fallback
function num(name, fallback) {
    const value = Number(env.get(name));
    return Number.isFinite(value) ? value : fallback;
}

// Hysteresis: on at TEMP_HIGH, off once the temperature has fallen
// TEMP_HYSTERESIS below it. In between the fan keeps its state, so it doesn't
// switch on and off with every reading near the threshold.
const high = num("TEMP_HIGH", 28);
const low = high - num("TEMP_HYSTERESIS", 2);
const t = msg.payload;

let auto = null;
if (t >= high) {
    auto = { state: "on", reason: `temperature ${t} °C ≥ ${high} °C` };
} else if (t <= low) {
    auto = { state: "off", reason: `temperature ${t} °C ≤ ${low} °C` };
}
if (!auto) {
    return null;
}
return { zone: msg.zone, actuator: "fan", auto };

// Number from the container environment (.env), or the fallback
function num(name, fallback) {
    const value = Number(env.get(name));
    return Number.isFinite(value) ? value : fallback;
}

// Hysteresis: open at SOIL_LOW, close at SOIL_HIGH. After a max-run cutoff
// (see the watchdog) the valve stays closed until its lockout ends.
const low = num("SOIL_LOW", 30);
const high = num("SOIL_HIGH", 45);
const m = msg.payload;
const key = `${msg.zone}/valve`;

let auto = null;
if (m <= low) {
    const until = (flow.get("lockout") || {})[key] || 0;
    if (Date.now() < until) {
        node.status({ fill: "yellow", shape: "ring", text: `${key} locked out` });
        return null;
    }
    auto = { state: "on", reason: `soil moisture ${m} % ≤ ${low} %` };
} else if (m >= high) {
    auto = { state: "off", reason: `soil moisture ${m} % ≥ ${high} %` };
}
if (!auto) {
    return null;
}
return { zone: msg.zone, actuator: "valve", auto };

// actuators/<zone>/<actuator>/mode, retained, set by an operator:
//   auto  the rules decide (default; an empty payload clears the override)
//   on    forced on
//   off   forced off
const ACTUATORS = ["fan", "valve"];
const parts = msg.topic.split("/");
const zone = parts[1];
const actuator = parts[2];
const mode = String(msg.payload).trim().toLowerCase() || "auto";
if (!zone || !ACTUATORS.includes(actuator) || !["auto", "on", "off"].includes(mode)) {
    node.warn(`ignored ${msg.topic}: expected actuators/<zone>/fan|valve/mode with auto, on or off`);
    return null;
}
const modes = flow.get("mode") || {};
modes[`${zone}/${actuator}`] = mode;
flow.set("mode", modes);
// Re-evaluate now rather than at the next reading
return { zone, actuator };

// Number from the container environment (.env), or the fallback
function num(name, fallback) {
    const value = Number(env.get(name));
    return Number.isFinite(value) ? value : fallback;
}

// Runs every 5 s. Closes a valve the rules opened when:
//   - its zone sent no soil_moisture reading for STALE_AFTER s (dead sensor or
//     device: don't water blind), or
//   - it has been open for VALVE_MAX_RUN s (stuck sensor, burst pipe). It then
//     stays closed for VALVE_LOCKOUT s, whatever the readings say.
// A valve an operator forced on (mode "on") is left alone.
const staleAfter = num("STALE_AFTER", 120) * 1000;
const maxRun = num("VALVE_MAX_RUN", 900) * 1000;
const lockoutFor = num("VALVE_LOCKOUT", 1800) * 1000;
const now = Date.now();
const last = flow.get("last") || {};
const seen = flow.get("seen") || {};
const lockout = flow.get("lockout") || {};

const out = [];
for (const [key, cmd] of Object.entries(last)) {
    const [zone, actuator] = key.split("/");
    if (actuator !== "valve" || cmd.state !== "on" || cmd.mode !== "auto") {
        continue;
    }
    const lastReading = (seen[zone] || {}).soil_moisture;
    let reason = null;
    if (!lastReading) {
        reason = "no soil_moisture reading since Node-RED started";
    } else if (now - lastReading > staleAfter) {
        reason = `no soil_moisture reading for ${Math.round((now - lastReading) / 1000)} s`;
    } else if (now - Date.parse(cmd.at) > maxRun) {
        reason = `open for over ${maxRun / 1000} s; locked out for ${lockoutFor / 1000} s`;
        lockout[key] = now + lockoutFor;
    }
    if (reason) {
        out.push({ zone, actuator, auto: { state: "off", reason } });
    }
}
flow.set("lockout", lockout);
return [out];

// Combines the rule's state with the operator's mode, and publishes a command
// on actuators/<zone>/<actuator>/set when the state or mode changes. Commands
// are retained, so a device that (re)connects gets its state straight away.
const key = `${msg.zone}/${msg.actuator}`;
const autos = flow.get("auto") || {};
if (msg.auto) {
    autos[key] = msg.auto;
    flow.set("auto", autos);
}

const mode = (flow.get("mode") || {})[key] || "auto";
let state;
let reason;
if (mode === "auto") {
    if (!autos[key]) {
        return null;  // no reading has decided yet
    }
    state = autos[key].state;
    reason = autos[key].reason;
} else {
    state = mode;
    reason = `manual override (mode ${mode})`;
}

const last = flow.get("last") || {};
if (last[key] && last[key].state === state && last[key].mode === mode) {
    return null;
}
const at = new Date().toISOString();
last[key] = { state, mode, at };
flow.set("last", last);

node.status({ fill: state === "on" ? "green" : "grey", shape: "dot", text: `${key} ${state} (${mode})` });
return {
    topic: `actuators/${key}/set`,
    payload: { state, mode, reason, at },
    retain: true,
    qos: 1,
};

// After a restart, picks up the last command for each actuator from its
// retained set topic, so Node-RED doesn't repeat it and the watchdog knows
// since when a valve has been open.
const parts = msg.topic.split("/");
const p = msg.payload;
if (!p || typeof p !== "object" || !["on", "off"].includes(p.state)) {
    return null;
}
const key = `${parts[1]}/${parts[2]}`;
const last = flow.get("last") || {};
if (!last[key]) {
    last[key] = { state: p.state, mode: p.mode || "auto", at: p.at || new Date().toISOString() };
    flow.set("last", last);
}
return null;
